command:
cat > /tmp/rabbitmq.config <<'EOF'
[
  {rabbit, [
    {tcp_listeners, []},
    {ssl_listeners, [5671]},
    {ssl_options, [
      {cacertfile, "/etc/rabbitmq/tls/ca.crt"},
      {certfile,   "/etc/rabbitmq/tls/server.crt"},
      {keyfile,    "/etc/rabbitmq/tls/server.key"},
      {verify, verify_peer},
      {fail_if_no_peer_cert, true},
      {versions, ['tlsv1.2']}
    ]},
    {cluster_partition_handling, autoheal}
  ]},
  {rabbitmq_management, [
    {listener, [
      {port, 15672},
      {ip, "__NODE_IP__"}
    ]}
  ]}
].
EOF
